mapper.select:
SELECT t.* FROM edu_collect_task t


        AND t.collect_task_name LIKE CONCAT('%', #{query.taskName}, '%')


        AND t.collect_task_source_type = #{query.sourceType}


        AND t.collect_task_subject = #{query.subject}


        AND t.collect_task_status = #{query.status}



            AND (t.collect_task_owner_user_id IS NULL OR t.collect_task_owner_user_id = #{scope.ownerPredicate})



ORDER BY t.collect_task_id DESC

mapper.update:
UPDATE edu_collect_task
SET collect_task_last_run_time = #{startTime},
    collect_task_last_run_status = #{lastRunStatus},
    collect_task_last_run_count = #{lastRunCount},
    collect_task_total_count = IFNULL(collect_task_total_count, 0) + #{savedCount}
WHERE collect_task_id = #{taskId}
